import '@servicenow/sdk/global'
import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'

// =============================================================================
// Test Flow: Simple WaitForADuration with Log Action
// Tests basic wait for duration functionality and output datapills
// =============================================================================
export const flowWaitForDurationSimple = Flow(
    {
        $id: Now.ID['flow-wait-duration-simple'],
        name: 'Wait For Duration Simple',
        description: 'WaitForADuration bi-directional test - simple',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['wait-duration-simple-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Wait for 5 seconds with explicit duration
        const waitResult = wfa.flowLogic.waitForADuration({
            $id: Now.ID['wait-duration-simple-wait'],
            durationType: 'explicit_duration',
            duration: Duration({
                days: 0,
                hours: 0,
                minutes: 0,
                seconds: 5,
            }),
        })

        // Log action using wait output datapills
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['wait-duration-simple-log'],
            },
            {
                log_level: 'info',
                log_message: `Wait completed. Duration: ${wfa.dataPill(waitResult.total_duration, 'string')}, End time: ${wfa.dataPill(waitResult.scheduled_end_date_time, 'string')}`,
            }
        )
    }
)
